<div class="container-fluid mt-2" id="efm-app">
    <div class="d-flex flex-wrap align-items-center gap-2 mb-2"><h2 class="me-3">Extended File Manager</h2><label for="efm-playlist" class="visually-hidden">Playlist</label><select id="efm-playlist" class="form-select" style="max-width:22rem"></select><button id="efm-add" class="btn btn-primary" type="button">Add selected to playlist</button></div>
    <p class="text-muted">Video media only. Folders are relative to FPP's video directory.</p><div id="efm-breadcrumb" class="mb-2"></div><div id="efm-message" role="status" class="mb-2"></div>
    <div class="table-responsive"><table class="table table-striped align-middle"><thead><tr><th scope="col"><input id="efm-all" type="checkbox" aria-label="Select all files"></th><th scope="col">Name</th><th scope="col">Type</th></tr></thead><tbody id="efm-list"></tbody></table></div>
</div>
<script>
(function(){const base='api/plugin/fpp-plugin-extended-file-manager/';let current='';const $=id=>document.getElementById(id);function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}function msg(t,c){$('efm-message').textContent=t||'';$('efm-message').className='mb-2 '+(c||'');}async function playlists(){const r=await fetch('api/playlists');const a=await r.json();$('efm-playlist').innerHTML=a.map(n=>'<option>'+esc(n)+'</option>').join('');}async function load(path){current=path||'';const r=await fetch(base+'media?path='+encodeURIComponent(current));const d=await r.json();if(!r.ok)return msg(d.error||'Unable to list media.','text-danger');$('efm-breadcrumb').innerHTML='<button class="btn btn-link p-0" data-path="">Videos</button>'+(current?' / '+esc(current):'');$('efm-list').innerHTML=d.items.map(i=>i.type==='directory'?'<tr><td></td><td colspan="2"><button class="btn btn-link p-0" data-path="'+esc(i.path)+'">📁 '+esc(i.name)+'</button></td></tr>':'<tr><td><input class="efm-file" type="checkbox" value="'+esc(i.path)+'" aria-label="Select '+esc(i.name)+'"></td><td>'+esc(i.name)+'</td><td>Video</td></tr>').join('');}document.addEventListener('click',e=>{if(e.target.dataset.path!==undefined)load(e.target.dataset.path);});$('efm-all').addEventListener('change',e=>document.querySelectorAll('.efm-file').forEach(x=>x.checked=e.target.checked));$('efm-add').addEventListener('click',async()=>{const paths=[...document.querySelectorAll('.efm-file:checked')].map(x=>x.value);if(!paths.length)return msg('Select at least one video.','text-warning');const r=await fetch(base+'add',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({playlist:$('efm-playlist').value,paths})});const d=await r.json();msg(r.ok?'Added '+d.added+' file(s); skipped '+d.skipped+' duplicate(s).':(d.error||'Unable to update playlist.'),r.ok?'text-success':'text-danger');});playlists().then(()=>load('')).catch(()=>msg('Unable to load FPP playlists.','text-danger'));})();
</script>
